*, *::before, *::after { box-sizing: border-box; }
html { color-scheme: light; text-size-adjust: 100%; }
body {
  margin: 0;
  color: var(--color-text);
  background: var(--color-canvas);
  font-family: var(--type-family-body);
  font-size: var(--type-size-body);
  line-height: var(--type-line-body);
  text-rendering: optimizeLegibility;
}
img, picture, video, canvas, svg { display: block; max-width: 100%; }
button, input, textarea, select { font: inherit; }
:focus-visible { outline: 3px solid var(--color-focus); outline-offset: 3px; }

.omni-page { min-height: 100%; }
.omni-header, .omni-nav, .omni-footer {
  width: min(100% - (2 * var(--layout-gutter)), var(--layout-content-max));
  margin-inline: auto;
}
.omni-section {
  width: min(100% - (2 * var(--layout-gutter)), var(--layout-content-max));
  margin-inline: auto;
  padding-block: var(--layout-section-space);
}
.omni-container {
  width: min(100% - (2 * var(--layout-gutter)), var(--layout-content-max));
  margin-inline: auto;
}
.omni-stack { display: flex; flex-direction: column; gap: var(--space-4); }
.omni-cluster { display: flex; flex-wrap: wrap; gap: var(--space-4); align-items: center; }
@media (max-width: 48rem) {
  .omni-section { padding-block: var(--space-12); }
}

